const items = $input.all();
const words = items.map(i => i.json);
const randomIdx = Math.floor(Math.random() * words.length);
const word = words[randomIdx];
const options = [word.translation];
while (options.length < 4) {
  const rnd = words[Math.floor(Math.random() * words.length)];
  if (!options.includes(rnd.translation)) options.push(rnd.translation);
}
// Shuffle
for (let i = options.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [options[i], options[j]] = [options[j], options[i]];
}
const correctIndex = options.indexOf(word.translation);
return [{
  json: {
    word: word.word,
    translation: word.translation,
    example: word.example || '',
    category: word.category || 'general',
    options,
    correctIndex,
    correctLetter: ['A', 'B', 'C', 'D'][correctIndex],
    date: new Date().toISOString().split('T')[0]
  }
}];

