const items = $input.all();
const results = [];
for (const item of items) {
  const text = (item.json.message?.text || '').trim().toUpperCase();
  const chatId = item.json.message?.chat?.id;
  const username = item.json.message?.from?.username || 'user';
  const validAnswers = ['A', 'B', 'C', 'D'];
  if (validAnswers.includes(text)) {
    results.push({
      json: {
        answer: text,
        chatId,
        username,
        isQuizAnswer: true,
        timestamp: new Date().toISOString()
      }
    });
  }
}
return results.length > 0 ? results : [{ json: { isQuizAnswer: false } }];
